#include "graph.h"
#include <stdlib.h>
#include <limits.h>
static int inside(int x,int y,int c,int r){return x>=0&&y>=0&&x<c&&y<r;}
int graph_bfs_grid(int c,int r,const unsigned char*w,DnPoint s,DnPoint g,DnPoint*out,int cap){if(c<=0||r<=0||c*r>GRAPH_MAX_NODES||!w||!inside(s.x,s.y,c,r)||!inside(g.x,g.y,c,r)||!w[g.y*c+g.x])return 0;int n=c*r,*prev=(int*)malloc(n*sizeof(int)),*q=(int*)malloc(n*sizeof(int));if(!prev||!q){free(prev);free(q);return 0;}for(int i=0;i<n;i++)prev[i]=-2;int si=s.y*c+s.x,gi=g.y*c+g.x,head=0,tail=0;q[tail++]=si;prev[si]=-1;int dx[]={1,-1,0,0},dy[]={0,0,1,-1};while(head<tail&&prev[gi]==-2){int u=q[head++],x=u%c,y=u/c;for(int k=0;k<4;k++){int nx=x+dx[k],ny=y+dy[k];if(!inside(nx,ny,c,r))continue;int v=ny*c+nx;if(!w[v]||prev[v]!=-2)continue;prev[v]=u;q[tail++]=v;}}int count=0;if(prev[gi]!=-2){for(int v=gi;v!=-1;v=prev[v])count++;if(out&&cap>0){int take=count<cap?count:cap;int v=gi;for(int i=count-1;i>=count-take;i--){out[i-(count-take)] = (DnPoint){v%c,v/c};v=prev[v];}count=take;}}else count=0;free(prev);free(q);return count;}
int graph_dijkstra_matrix(int n,const int*w,int s,int g,int*out,int cap){if(n<=0||n>GRAPH_MAX_NODES||!w||s<0||g<0||s>=n||g>=n)return 0;int*d=malloc(n*sizeof(int)),*p=malloc(n*sizeof(int)),*used=calloc(n,sizeof(int));if(!d||!p||!used){free(d);free(p);free(used);return 0;}for(int i=0;i<n;i++){d[i]=INT_MAX/4;p[i]=-1;}d[s]=0;for(int z=0;z<n;z++){int u=-1;for(int i=0;i<n;i++)if(!used[i]&&(u<0||d[i]<d[u]))u=i;if(u<0||d[u]>=INT_MAX/4)break;used[u]=1;for(int v=0;v<n;v++){int wt=w[u*n+v];if(wt>0&&!used[v]&&d[u]+wt<d[v]){d[v]=d[u]+wt;p[v]=u;}}}int count=0;if(d[g]<INT_MAX/4){for(int v=g;v!=-1;v=p[v])count++;if(out&&cap>0){int take=count<cap?count:cap,v=g;for(int i=count-1;i>=count-take;i--){out[i-(count-take)]=v;v=p[v];}count=take;}}else count=0;free(d);free(p);free(used);return count;}
